			/**
			 * 목록화면에서 전달받은 정보구성
			 ** @param {"CREATE" | "READ"} psType 게시글 상세 조회 타입
			 * @param {any} poData 데이터
			 */
			function setDtlData(psType, poData) {
			    var voDsBrdDtlList = app.lookup("dsBoardList");
			    var voDmDtlParma = app.lookup("dmDtlParam");
			    
			    if (!poData) return;
			    
			    voDmDtlParma.build(poData);
			    
			    if (psType == "CREATE") {
			        voDsBrdDtlList.clear();
			        voDsBrdDtlList.insertRowData(0, true, poData);
			        
			    } else if (psType == "READ") {
			        doDtlList();
			    } else if (psType == "chatt") {
			        
			        chattYn = true;
			        
			        util.Control.setVisible(app, false, "btnSave");
			        util.Control.setVisible(app, false, "btnList");
			        
			        app.lookup("ipbClienaIndvIdntfcNo").putValue(poData["CLIENA_ID"]);
			        app.lookup("ipbClienaNm").putValue(poData["CLIENA_NM_ENCPT"]);
			        app.lookup("ipbCntnIpAddr").putValue(poData["CNTN_IP_ADDR"]);
			        
			        doDtlList(psType);
			    }
			    
			    setDtlCrud(psType);
			}
			exports.setDtlData = setDtlData;

